const listOverdueRentalOrganizations = `-- name: ListOverdueRentalOrganizations :many
SELECT DISTINCT r.organization_id
FROM rentals r
JOIN reservations res ON res.organization_id = r.organization_id AND res.id = r.reservation_id
JOIN vehicle_allocations a ON a.organization_id = r.organization_id AND a.id = r.allocation_id
WHERE r.status = 'active'
  AND a.status = 'active'
  AND a.ends_at <= $1::timestamptz
  AND res.ends_at + make_interval(mins => COALESCE(NULLIF(r.policy_snapshot -> 'policies' ->> 'late_return_grace_minutes', '')::int, 0))
      <= $1::timestamptz
LIMIT 1000
`

// Organizations with active rentals whose vehicle should be back by now
// (planned return + late tolerance passed and the engine allocation ended).
func (q *Queries) ListOverdueRentalOrganizations(ctx context.Context, nowAt pgtype.Timestamptz) ([]int64, error) {
	rows, err := q.db.Query(ctx, listOverdueRentalOrganizations, nowAt)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []int64{}
	for rows.Next() {
		var organization_id int64
		if err := rows.Scan(&organization_id); err != nil {
			return nil, err
		}
		items = append(items, organization_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listOverdueRentals = `-- name: ListOverdueRentals :many
SELECT r.uuid
FROM rentals r
JOIN reservations res ON res.organization_id = r.organization_id AND res.id = r.reservation_id
JOIN vehicle_allocations a ON a.organization_id = r.organization_id AND a.id = r.allocation_id
WHERE r.organization_id = $1
  AND res.organization_id = $1
  AND a.organization_id = $1
  AND r.status = 'active'
  AND a.status = 'active'
  AND a.ends_at <= $2::timestamptz
  AND res.ends_at + make_interval(mins => COALESCE(NULLIF(r.policy_snapshot -> 'policies' ->> 'late_return_grace_minutes', '')::int, 0))
      <= $2::timestamptz
ORDER BY r.id
LIMIT 500
`

